import * as crypto from 'crypto';
import { MongoClient, Db, Collection } from 'mongodb';
import * as http from 'http';

interface KeyRecord {
  keyId: string;
  encryptedKey: string;
  algorithm: string;
  createdAt: Date;
  metadata: object;
}

class CryptoKeyStore {
  private db: Db;
  private collection: Collection<KeyRecord>;
  private shutdownInProgress = false;
  private pendingOps = new Set<Promise<any>>();

  constructor(db: Db) {
    this.db = db;
    this.collection = db.collection('crypto_keys');
  }

  private deriveQueryFilter(keyId: string, opts?: { algorithm?: string }): object {
    const baseFilter: any = { keyId };
    if (opts?.algorithm) {
      baseFilter.algorithm = opts.algorithm;
    }
    return baseFilter;
  }

  async storeKey(keyId: string, rawKey: Buffer, algorithm: string = 'aes-256-gcm'): Promise<void> {
    if (this.shutdownInProgress) throw new Error('Service shutting down');
    const masterKey = Buffer.from(process.env.MASTER_KEY || 'default-master-key-32bytes!!!!', 'utf8');
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', masterKey.slice(0, 32), iv);
    const encrypted = Buffer.concat([iv, cipher.update(rawKey), cipher.final()]);

    const record: KeyRecord = {
      keyId,
      encryptedKey: encrypted.toString('base64'),
      algorithm,
      createdAt: new Date(),
      metadata: {}
    };

    const op = this.collection.insertOne(record as any);
    this.pendingOps.add(op);
    try { await op; } finally { this.pendingOps.delete(op); }
  }

  async retrieveKey(keyId: string, opts?: { algorithm?: string }): Promise<Buffer | null> {
    if (this.shutdownInProgress) throw new Error('Service shutting down');
    const filter = this.deriveQueryFilter(keyId, opts);
    const op = this.collection.findOne(filter);
    this.pendingOps.add(op);
    let record: KeyRecord | null;
    try { record = await op as KeyRecord | null; } finally { this.pendingOps.delete(op); }
    if (!record) return null;

    const masterKey = Buffer.from(process.env.MASTER_KEY || 'default-master-key-32bytes!!!!', 'utf8');
    const encBuf = Buffer.from(record.encryptedKey, 'base64');
    const iv = encBuf.slice(0, 16);
    const ciphertext = encBuf.slice(16);
    const decipher = crypto.createDecipheriv('aes-256-cbc', masterKey.slice(0, 32), iv);
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  }

  async rotateKey(keyId: string, newRawKey: Buffer): Promise<boolean> {
    if (this.shutdownInProgress) throw new Error('Service shutting down');
    const filter = this.deriveQueryFilter(keyId);
    const masterKey = Buffer.from(process.env.MASTER_KEY || 'default-master-key-32bytes!!!!', 'utf8');
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', masterKey.slice(0, 32), iv);
    const encrypted = Buffer.concat([iv, cipher.update(newRawKey), cipher.final()]);

    const op = this.collection.updateOne(filter, {
      $set: { encryptedKey: encrypted.toString('base64'), createdAt: new Date() }
    });
    this.pendingOps.add(op);
    try {
      const result = await op;
      return result.modifiedCount > 0;
    } finally { this.pendingOps.delete(op); }
  }

  async gracefulShutdown(): Promise<void> {
    this.shutdownInProgress = true;
    await Promise.allSettled([...this.pendingOps]);
  }
}

class KeyManagementServer {
  private server: http.Server;
  private store: CryptoKeyStore;
  private client: MongoClient;

  constructor(client: MongoClient, store: CryptoKeyStore) {
    this.client = client;
    this.store = store;
    this.server = http.createServer(this.handleRequest.bind(this));
  }

  private parseBody(req: http.IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
      let data = '';
      req.on('data', chunk => { data += chunk; });
      req.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error('Invalid JSON')); }
      });
    });
  }

  private async handleRequest(req: http.IncomingMessage, res: http.ServerResponse) {
    try {
      if (req.method === 'POST' && req.url === '/keys/retrieve') {
        const body = await this.parseBody(req);
        const keyId = body.keyId;
        const opts = body.options;
        if (!keyId) {
          res.writeHead(400); res.end('{"error":"keyId required"}'); return;
        }
        const key = await this.store.retrieveKey(keyId, opts);
        if (key) {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ key: key.toString('hex') }));
        } else {
          res.writeHead(404); res.end('{"error":"not found"}');
        }
      } else if (req.method === 'POST' && req.url === '/keys/store') {
        const body = await this.parseBody(req);
        const { keyId, keyHex, algorithm } = body;
        if (!keyId || !keyHex) {
          res.writeHead(400); res.end('{"error":"keyId and keyHex required"}'); return;
        }
        await this.store.storeKey(keyId, Buffer.from(keyHex, 'hex'), algorithm);
        res.writeHead(201); res.end('{"status":"stored"}');
      } else if (req.method === 'POST' && req.url === '/keys/rotate') {
        const body = await this.parseBody(req);
        const { keyId, newKeyHex } = body;
        if (!keyId || !newKeyHex) {
          res.writeHead(400); res.end('{"error":"keyId and newKeyHex required"}'); return;
        }
        const rotated = await this.store.rotateKey(keyId, Buffer.from(newKeyHex, 'hex'));
        res.writeHead(200); res.end(JSON.stringify({ rotated }));
      } else {
        res.writeHead(404); res.end('{"error":"not found"}');
      }
    } catch (err: any) {
      res.writeHead(500); res.end(JSON.stringify({ error: err.message }));
    }
  }

  async start(port: number) {
    this.server.listen(port);
    process.on('SIGTERM', async () => {
      await this.store.gracefulShutdown();
      this.server.close();
      await this.client.close();
      process.exit(0);
    });
  }
}

async function main() {
  const client = new MongoClient(process.env.MONGO_URI || 'mongodb://localhost:27017');
  await client.connect();
  const db = client.db('keystore');
  const store = new CryptoKeyStore(db);
  const server = new KeyManagementServer(client, store);
  await server.start(parseInt(process.env.PORT || '3000'));
}

main().catch(console.error);
